import sys

class Vehicle:
    def __init__(self, price):
        self.price = price

class Car(Vehicle):
    def __init__(self, price, fuel_type):
        super().__init__(price)
        self.fuel_type = fuel_type

class ElectricCar(Car):
    def __init__(self, price, fuel_type, battery_capacity):
        super().__init__(price, fuel_type)
        self.battery_capacity = battery_capacity

    def calculate_tax(self):
        base_tax = self.price * 0.10
        if self.fuel_type.lower() == "electric":
            base_tax *= 0.5
        return int(base_tax)

def main():
    lines = sys.stdin.read().strip().split()
    price = int(lines[0])
    fuel_type = lines[1]
    battery_capacity = int(lines[2])

    v = ElectricCar(price, fuel_type, battery_capacity)
    tax = v.calculate_tax()
    print(f"Final Tax: {tax}")

if __name__ == "__main__":
    main()
